{
  "name": "TTi QL355TP 可编程多路直流电源",
  "name_en": "TTi QL355TP Programmable Multi-Output DC Power Supply",
  "manufacturer": "TTi (Thurlby Thandar Instruments)",
  "description": "用于实验室供电的台式可编程直流电源，支持多个输出通道的开关控制，并可设置与读取电压、电流及限流参数，适合电子器件测试、原型验证和实验系统供电。",
  "description_en": "A bench programmable DC power supply for laboratory use. It supports enabling multiple output channels and setting or reading voltage, current, and current-limit parameters, making it suitable for electronics testing, prototyping, and powering experimental setups.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化电源通信并准备设备使用。",
      "description_en": "Initialize communication with the power supply and prepare it for use."
    },
    {
      "action_name": "auto-reinit",
      "description": "重新初始化电源连接与设备状态。",
      "description_en": "Reinitialize the power supply connection and device state."
    },
    {
      "action_name": "auto-write",
      "description": "向电源发送底层控制命令。",
      "description_en": "Send a low-level control command to the power supply."
    },
    {
      "action_name": "auto-ask",
      "description": "向电源发送查询命令并获取响应。",
      "description_en": "Send a query command to the power supply and get the response."
    },
    {
      "action_name": "auto-read",
      "description": "读取电源返回的数据。",
      "description_en": "Read response data returned by the power supply."
    },
    {
      "action_name": "auto-set_enable",
      "description": "打开或关闭指定输出通道，可作用于 OP1、OP2、AUX 或全部通道。",
      "description_en": "Enable or disable a selected output channel, including OP1, OP2, AUX, or all channels."
    },
    {
      "action_name": "auto-get_name",
      "description": "读取电源名称或型号标识。",
      "description_en": "Read the power supply name or model identification."
    },
    {
      "action_name": "auto-get_current",
      "description": "读取指定输出通道（OP1 或 OP2）的输出电流。",
      "description_en": "Read the output current of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-get_voltage",
      "description": "读取指定输出通道（OP1 或 OP2）的输出电压。",
      "description_en": "Read the output voltage of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-get_set_voltage",
      "description": "读取指定输出通道（OP1 或 OP2）的电压设定值。",
      "description_en": "Read the configured voltage setpoint of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-get_current_limit",
      "description": "读取指定输出通道（OP1 或 OP2）的限流设定值。",
      "description_en": "Read the current-limit setting of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置指定输出通道（OP1 或 OP2）的输出电压。",
      "description_en": "Set the output voltage of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-set_current_limit",
      "description": "设置指定输出通道（OP1 或 OP2）的电流限制。",
      "description_en": "Set the current limit of the selected channel (OP1 or OP2)."
    },
    {
      "action_name": "auto-reset_trip",
      "description": "复位电源的跳闸或保护状态。",
      "description_en": "Reset the power supply trip or protection state."
    }
  ],
  "tag_hints": [
    "programmable DC power supply",
    "bench power supply",
    "multi-output power supply",
    "voltage sourcing",
    "current limiting",
    "electrical test equipment"
  ]
}

